      let guidanceZ=pipZ;
      const traj=m._samTrajPlan, loftProf=_samTrajectoryProfileFor(m)?.loft||{};
      const urgency=traj?.urgency??0, loftDemand0=traj?.loftDemand??0;
      let terminalFade=1;
      if(traj){
        const startR=traj.terminalBlendStartKm??20,fullR=traj.terminalBlendFullKm??8;
